.mill { --acc: #8a9a1f; --acc-hi: #b8c94a; --panel: rgba(120,110,90,.08); --line: rgba(120,110,90,.35); display: flex; flex-direction: column; gap: .6rem; max-width: 100%; overflow: hidden; color: var(--figure-text, inherit); }
html[data-theme=dark] .mill { --acc: #a6b83a; --acc-hi: #d2e266; --panel: rgba(220,210,190,.07); --line: rgba(220,210,190,.3); }
.mill-controls { display: flex; flex-wrap: wrap; gap: .4rem; align-items: center; }
.mill-controls button { font: inherit; font-size: .9rem; padding: .35rem .75rem; border-radius: 6px; border: 1px solid var(--line); background: var(--panel); color: inherit; cursor: pointer; }
.mill-controls button:hover { border-color: var(--acc); }
.mill-controls button:focus-visible, .mill-rpm input:focus-visible { outline: 2px solid var(--acc); outline-offset: 2px; }
#play[aria-pressed=true] { background: var(--acc); color: #fff; border-color: var(--acc); }
.mill-rpm { display: flex; align-items: center; gap: .4rem; font-size: .85rem; flex: 1 1 14rem; min-width: 0; }
.mill-rpm input { flex: 1; min-width: 6rem; accent-color: var(--acc); }
.mill-rpm output { font-variant-numeric: tabular-nums; min-width: 4.2em; }
.mill-status { margin: 0; font-size: .85rem; padding: .25rem .6rem; border-left: 3px solid var(--acc); background: var(--panel); }
.mill-art { width: 100%; }
.mill-art svg { display: block; width: 100%; height: auto; }
.mill .acc.iso-shade, .mill .acc.iso-top { fill: var(--acc); }
.mill .acc.iso-top { fill: var(--acc-hi); }
.mill-mark circle { fill: var(--acc); stroke: #fff; stroke-width: 1.2; }
html[data-theme=dark] .mill-mark circle { stroke: #222; }
.mill-mark text { fill: #fff; font: 600 10px system-ui, sans-serif; }
.mill-readout { display: grid; grid-template-columns: repeat(auto-fit, minmax(10.5rem, 1fr)); gap: .3rem .8rem; margin: 0; font-size: .82rem; }
.mill-readout div { display: flex; justify-content: space-between; gap: .5rem; border-bottom: 1px solid var(--line); padding: .15rem 0; }
.mill-readout dt { color: var(--figure-muted, inherit); }
.mill-readout dd { margin: 0; font-variant-numeric: tabular-nums; }
.mill-legend { margin: 0; padding-left: 1.4rem; font-size: .8rem; color: var(--figure-muted, inherit); columns: 2 18rem; }
.mill-notes { font-size: .82rem; }
.mill-notes summary { cursor: pointer; }
.mill .lk-cut { fill: #d8a35e; stroke: #8a5a22; stroke-width: .6; }
html[data-theme=dark] .mill .lk-cut { fill: #8a5f2c; stroke: #e0b070; }

model:
// Steam-driven three-roller cane mill. Pure model; world x right, y along roller axes, z up.
// Topology: engine crank (shaft C, axis y) -> pinion 20T -> main gear 60T on top roller shaft T ->
// crown gears 31T (top) meshing with 31T on feed roller F and discharge roller D (rear, y<0).
// Cane route lies in the xz plane: chute line -> feed nip N1 -> arc around T over turnplate -> nip N2 -> exit line.
// Idealized kinematics: no forces, steam pressure or real extraction physics.
import {externalGearPair, sliderCrank} from '/leitor/mechanics.mjs'
export const R = 3, L = 9, GAP = 0.2, CANE = 0.45, STALK = 5, CHUTE = 6.5, EXIT = 6
export const crown = externalGearPair({teethA: 31, teethB: 31, module: 0.2, samples: 8})
export const drive = externalGearPair({teethA: 60, teethB: 20, module: 0.2, samples: 8})
const CD = crown.distance // = 2R + GAP
export const zB = 4.2, zT = zB + 4.2
const A = Math.sqrt(CD * CD - 4.2 * 4.2)
export const T = [0, zT], F = [-A, zB], D = [A, zB]
const dirC = Math.atan2(-0.55, 1) // main gear -> pinion direction in xz
export const C = [T[0] + drive.distance * Math.cos(dirC), T[1] + drive.distance * Math.sin(dirC)]
export const crank = {radius: 1.6, rodLength: 6.2, side: 1}
// Cane runs in one lane close to the front housing; the optional inspection section plane passes through that lane.
export const LANE = L - 1.0
export const Y = {rearCheek: [-1.2, 0], frontCheek: [L, L + 1.2], crownG: [-2.3, -1.5], mainG: [-3.4, -2.6],
  crankPlane: -4.4, lanes: [LANE], cut: LANE, roller: [0.05, L - 0.05]}
export const JR = 0.9, BR = 1.0 // journal radius, bearing bore radius in both cheeks
export const ROD_EXT = 4.5 // crosshead to piston centre along the piston rod
export const BORE = {x0: C[0] + 8.1, len: 5.4, r: 1.05} // cylinder bore start (x), length, radius; piston r 1.0, length 1.2
// Front housing as an open frame (xz rectangles + bearing bosses) so the nips stay visible; same y as frontCheek.
export const FRAME = {boss: 1.7, bars: [
  [-8.5, 8.5, 0.8, 1.7], [-8.5, -7.3, 0.8, 6.7], [7.3, 8.5, 0.8, 10.0], [1.4, 7.3, 9.2, 10.0],
  [-7.3, -6.0, 3.6, 4.8], [-5.1, -4.0, 1.7, 2.7], [6.0, 7.3, 3.6, 4.8], [4.0, 5.1, 1.7, 2.7]]}
const th1 = Math.atan2(F[1] - T[1], F[0] - T[0]), th2 = Math.atan2(D[1] - T[1], D[0] - T[0])
export const RA = R + GAP / 2, ARC = RA * (th2 - th1)
export const N1 = [T[0] + RA * Math.cos(th1), T[1] + RA * Math.sin(th1)]
export const N2 = [T[0] + RA * Math.cos(th2), T[1] + RA * Math.sin(th2)]
const t1 = [-Math.sin(th1), Math.cos(th1)], t2 = [-Math.sin(th2), Math.cos(th2)]
export const S_NIP1 = CHUTE, S_NIP2 = CHUTE + ARC, S_END = CHUTE + ARC + EXIT
// route point and tangent at arc length s
export function route(s) {
  if (s <= S_NIP1) { const d = s - S_NIP1; return {p: [N1[0] + t1[0] * d, N1[1] + t1[1] * d], t: t1} }
  if (s <= S_NIP2) { const a = th1 + (s - S_NIP1) / RA; return {p: [T[0] + RA * Math.cos(a), T[1] + RA * Math.sin(a)], t: [-Math.sin(a), Math.cos(a)]} }
  const d = s - S_NIP2; return {p: [N2[0] + t2[0] * d, N2[1] + t2[1] * d], t: t2}
}
// material thickness at s: round cane until squeezed, then ribbon equal to gap
export function thickness(s) {
  if (s >= S_NIP1) return GAP
  const {p} = route(s)
  const room = 2 * Math.min(Math.hypot(p[0] - T[0], p[1] - T[1]) - R, Math.hypot(p[0] - F[0], p[1] - F[1]) - R)
  return Math.max(GAP, Math.min(CANE, room))
}
export const RPM_MIN = 20, RPM_MAX = 90
export function initial() { return {crank: 0, rpm: 50, running: false, stalks: [], fed: 0, done: 0, juice: 0, msg: 'Ready: feed a cane stalk'} }
export const ratio = 20 / 60 // top roller turns per crank turn
export function pose(st) {
  // st.crank is the advanced angle; the crank turns clockwise in xz, so the top roller turns CCW
  // and its underside (and the cane) moves toward +x. Crank angle in xz = -st.crank.
  const sc = sliderCrank(crank, -st.crank)
  const phiTop = st.crank * ratio // CCW in xz
  const gp = drive.phaseAt(phiTop - dirC) // driver = main gear in rotated pair frame
  const pin = gp[1] + dirC
  const pf = crown.phaseAt(phiTop - th1), pd = crown.phaseAt(phiTop - th2)
  return {sc, phiTop, main: phiTop, pinion: pin, top: phiTop, feed: pf[1] + th1, disc: pd[1] + th2, crossX: C[0] + sc.slider[0], pistonX: C[0] + sc.slider[0] + ROD_EXT}
}
export const surfaceSpeed = rpm => rpm * ratio * 2 * Math.PI * R / 60 // units/s
export const JUICE = {n1: 0.42, n2: 0.18} // litres per stalk at each nip (idealized)
export function feed(st) {
  const s = {...st, stalks: st.stalks.map(x => ({...x}))}
  if (s.stalks.some(x => x.s - STALK < STALK + 0.5)) { s.msg = 'Blocked: feed chute still occupied'; return s }
  if (s.stalks.length >= 3) { s.msg = 'Blocked: mill full'; return s }
  s.stalks.push({s: STALK, lane: LANE, id: s.fed}); s.fed++
  s.msg = s.running ? 'Stalk fed into chute' : 'Stalk waiting on chute: start the engine'
  return s
}
const clamp01 = v => Math.max(0, Math.min(1, v))
export function advanceCrank(st, dA) {
  const ds = dA * ratio * R // roller surface travel for crank rotation dA
  const s = {...st, crank: st.crank + dA, stalks: []}
  let juice = st.juice, done = st.done
  for (const x of st.stalks) {
    const n = x.s + ds
    for (const [k, sn] of [['n1', S_NIP1], ['n2', S_NIP2]]) juice += JUICE[k] * (clamp01((n - sn) / STALK) - clamp01((x.s - sn) / STALK))
    if (n - STALK >= S_END) { done++; continue }
    s.stalks.push({...x, s: n})
  }
  s.juice = juice; s.done = done
  if (done > st.done) s.msg = 'Bagasse discharged'
  else if (s.stalks.length && ds > 0) s.msg = stageMsg(s.stalks[0])
  return s
}
// describes where the oldest stalk is, from its head (x.s) and tail (x.s - STALK) arc positions
export function stageMsg(x) {
  const tail = x.s - STALK
  if (x.s < S_NIP1) return 'Stalk on the chute, sliding toward the feed nip'
  if (tail < S_NIP1) return gripMsg(x)
  if (x.s < S_NIP2) return 'Crushed once: the ribbon rides over the turnplate toward the discharge nip'
  if (tail < S_NIP2) return `Second squeeze at the discharge nip: ${Math.round(100 * clamp01((x.s - S_NIP2) / STALK))}% through`
  return 'Bagasse ribbon leaving the discharge nip'
}
// head of the stalk (s) has passed the feed nip; tail = s - STALK
export function gripMsg(x) {
  const pct = Math.round(100 * clamp01((x.s - S_NIP1) / STALK))
  return x.s - STALK < S_NIP1
    ? `Stalk gripped at feed nip: ${pct}% of its length crushed, tail still on the chute ${(S_NIP1 - (x.s - STALK)).toFixed(2)} units short of the nip`
    : 'Stalk gripped at feed nip: whole length crushed once, now heading for the discharge nip'
}
export const advance = (st, dt) => st.running ? advanceCrank(st, st.rpm / 60 * 2 * Math.PI * dt) : st

