import * as M from './model.mjs'
const W = (a) => ((a % (2 * Math.PI)) + 2 * Math.PI) % (2 * Math.PI)
const near = (a, b, e = 1e-6) => Math.abs(a - b) < e
export function verify() {
  const out = [], add = (name, passed, detail = '') => out.push({name, passed: !!passed, detail})
  const dist = (p, q) => Math.hypot(p[0] - q[0], p[1] - q[1])
  // roller nips: centre distance equals crown gear centre distance, gap positive
  add('feed nip gap equals setting', near(dist(M.T, M.F) - 2 * M.R, M.GAP), (dist(M.T, M.F) - 2 * M.R).toFixed(4))
  add('discharge nip gap equals setting', near(dist(M.T, M.D) - 2 * M.R, M.GAP))
  add('feed and discharge crown gears clear', dist(M.F, M.D) > 2 * M.crown.first.tipRadius + 0.2)
  add('pinion mesh distance', near(dist(M.T, M.C), M.drive.distance))
  // sampled cycle: crank pin, piston in bore, pinion/crank same shaft, roller ratio
  let pinOk = true, boreOk = true, shaftOk = true, minX = 1e9, maxX = -1e9, surfOk = true
  for (let i = 0; i <= 72; i++) {
    const st = {...M.initial(), crank: i * Math.PI / 36}, p = M.pose(st)
    if (!near(Math.hypot(...p.sc.pin), M.crank.radius) || !near(dist(p.sc.pin, p.sc.slider), M.crank.rodLength)) pinOk = false
    minX = Math.min(minX, p.pistonX); maxX = Math.max(maxX, p.pistonX)
    const d = W(p.pinion - (-st.crank)) , d0 = W(M.pose(M.initial()).pinion)
    if (!near(W(d - d0 + 1e-9), 0, 1e-6) && !near(W(d - d0 + 1e-9), 2 * Math.PI, 1e-6)) shaftOk = false
    // contact: top roller surface speed equals bottom roller surface speed (opposite rotation)
    const q = M.pose({...st, crank: st.crank + 0.01})
    if (!near((q.top - p.top) + (q.feed - p.feed), 0, 1e-9)) surfOk = false
  }
  add('slider-crank closure over cycle', pinOk)
  add('pinion turns with crankshaft', shaftOk)
  add('crown gears counter-rotate at equal speed', surfOk)
  const pistonLen = 1.2
  add('piston stays inside cylinder bore', minX - pistonLen / 2 >= M.BORE.x0 + 0.3 && maxX + pistonLen / 2 <= M.BORE.x0 + M.BORE.len - 0.3, `${minX.toFixed(2)}..${maxX.toFixed(2)}`)
  add('stroke equals twice crank radius', near(maxX - minX, 2 * M.crank.radius, 1e-3))
  // route continuity
  let cont = true
  for (const s of [M.S_NIP1, M.S_NIP2]) {
    const a = M.route(s - 1e-6), b = M.route(s + 1e-6)
    if (dist(a.p, b.p) > 1e-4 || Math.abs(a.t[0] * b.t[0] + a.t[1] * b.t[1] - 1) > 1e-4) cont = false
  }
  add('route position and tangent continuous at nips', cont)
  add('route passes through both nip points', dist(M.route(M.S_NIP1).p, M.N1) < 1e-9 && dist(M.route(M.S_NIP2).p, M.N2) < 1e-9)
  // ribbon between top roller and bottom rollers / turnplate stays clear
  let clear = true
  for (let s = M.S_NIP1; s <= M.S_NIP2; s += 0.05) {
    const p = M.route(s).p, h = M.thickness(s) / 2
    if (Math.hypot(p[0] - M.T[0], p[1] - M.T[1]) - h < M.R - 1e-9) clear = false
    if (Math.hypot(p[0] - M.F[0], p[1] - M.F[1]) - h < M.R - 1e-9) clear = false
    if (Math.hypot(p[0] - M.D[0], p[1] - M.D[1]) - h < M.R - 1e-9) clear = false
  }
  add('ribbon fits nips without penetrating rollers', clear)
  add('cane squeezed from round to ribbon', near(M.thickness(0), M.CANE) && near(M.thickness(M.S_NIP1), M.GAP))
  // state transitions
  let st = M.feed(M.initial())
  add('feeding places a stalk', st.stalks.length === 1)
  const blocked = M.feed(st)
  add('second feed is blocked while chute occupied', blocked.stalks.length === 1 && /Blocked/.test(blocked.msg))
  add('stopped engine does not move cane', M.advance(st, 5).stalks[0].s === st.stalks[0].s)
  let run = {...st, running: true}, t = 0
  while (run.done === 0 && t < 600) { run = M.advance(run, 0.1); t += 0.1 }
  add('stalk crosses both nips and discharges', run.done === 1 && run.stalks.length === 0, `t=${t.toFixed(1)}`)
  add('juice equals both nip shares', near(run.juice, M.JUICE.n1 + M.JUICE.n2, 1e-9), run.juice.toFixed(4))
  const one = M.advanceCrank(st, 2 * Math.PI)
  add('one crank turn moves cane one third roller circumference', near(one.stalks[0].s - st.stalks[0].s, 2 * Math.PI * M.R / 3))
  return out
}
// 3D housing, lane and message consistency checks (appended)
export function verifyExtra1() {
  const out = [], add = (name, passed, detail = '') => out.push({name, passed: !!passed, detail})
  const dist = (p, q) => Math.hypot(p[0] - q[0], p[1] - q[1])
  const centres = [M.T, M.F, M.D]
  const inBar = (x, z, b) => x >= b[0] && x <= b[1] && z >= b[2] && z <= b[3]
  // every boss annulus touches at least one frame bar (sample ring between bore and boss radius)
  let tied = true
  for (const c of centres) {
    let hit = false
    for (let i = 0; i < 72 && !hit; i++) { const a = i * Math.PI / 36, r = M.FRAME.boss - 0.05; for (const b of M.FRAME.bars) if (inBar(c[0] + r * Math.cos(a), c[1] + r * Math.sin(a), b)) hit = true }
    if (!hit) tied = false
  }
  add('each front bearing boss is tied to the housing frame', tied)
  let barsClear = true
  for (const c of centres) for (const b of M.FRAME.bars) {
    const nx = Math.max(b[0], Math.min(c[0], b[1])), nz = Math.max(b[2], Math.min(c[1], b[3]))
    if (Math.hypot(nx - c[0], nz - c[1]) < M.BR + 0.2) barsClear = false
  }
  add('frame bars leave bores open and bosses separate', barsClear && dist(M.T, M.F) > 2 * M.FRAME.boss && dist(M.F, M.D) > 2 * M.FRAME.boss && M.JR < M.BR)
  const wMax = Math.PI * M.CANE * M.CANE / 4 / M.GAP
  add('ribbon lane and section plane lie inside the roller length between cheeks', M.Y.cut === M.LANE && M.LANE - Math.min(1.6, wMax) / 2 >= M.Y.roller[0] && M.LANE + Math.min(1.6, wMax) / 2 <= M.Y.roller[1] && M.Y.rearCheek[1] <= M.Y.roller[0] && M.Y.roller[1] <= M.Y.frontCheek[0], `lane ${M.LANE}`)
  const st = M.feed(M.initial()), one = M.advanceCrank(st, 2 * Math.PI), x = one.stalks[0]
  add('after one rev the tail has not yet reached the feed nip and the message says so', x.s >= M.S_NIP1 && x.s - M.STALK < M.S_NIP1 && /tail still on the chute/.test(one.msg) && /gripped at feed nip/.test(one.msg), one.msg)
  let run = {...st, running: true}, prev = 0, mono = true
  for (let i = 0; i < 80; i++) { run = M.advance(run, 0.05); if (run.juice < prev - 1e-12) mono = false; prev = run.juice }
  add('juice never decreases while running', mono)
  return out
}

