import * as M from './model.mjs'
import {scene, draw, k} from './geometry.mjs'

const MARKS = [
  ['Feed nip: round cane meets the feed and top rollers', () => [M.N1[0] - 0.6, M.L + 2.2, M.N1[1] - 0.8]],
  ['Discharge nip: the ribbon is squeezed a second time', () => [M.N2[0] + 0.6, M.L + 2.2, M.N2[1] - 0.8]],
  ['Main gear 60T on the top-roller shaft, driven by the 20T pinion', () => [M.T[0] - 3, -3.4, M.T[1] + 5.4]],
  ['Crown gears 31T: the top roller drives feed and discharge rollers, which both turn opposite to it', () => [M.F[0] - 2.4, -2.3, M.F[1] + 2.6]],
  ['Disc crank, connecting rod and crosshead (slider-crank)', () => [M.C[0], -5.2, M.C[1] + 2.4]],
  ['Steam cylinder, cut open to show the piston', () => [M.BORE.x0 + 4.2, -5.2, M.C[1] + 1.5]],
]

export function mount(root, env = {}) {
  let st = M.initial(), playing = false, last = null, raf = 0, S = null, W = 0, H = 0, visible = true, alive = true, cut = false
  root.classList.add('mill')
  root.dataset.theme = env.theme || 'light'
  root.innerHTML = `
  <div class="mill-controls" role="group" aria-label="Mill controls">
    <button id="play" type="button" aria-pressed="false">Play</button>
    <button id="feed" type="button">Feed cane</button>
    <button id="step" type="button">Turn crank 1 rev</button>
    <button id="reset" type="button">Reset</button>
    <button id="cut" type="button" aria-pressed="false">Inspection: remove front cheek</button>
    <label class="mill-rpm" for="rpm">Engine speed <input id="rpm" type="range" min="${M.RPM_MIN}" max="${M.RPM_MAX}" step="5" value="${st.rpm}"> <output id="rpmv"></output></label>
  </div>
  <p id="status" class="mill-status" role="status" aria-live="polite"></p>
  <div class="mill-art"><svg id="art" role="img" aria-label="Isometric steam-driven three-roller sugar-cane mill"></svg></div>
  <dl id="readout" class="mill-readout"></dl>
  <ol class="mill-legend">${MARKS.map(m => `<li>${m[0]}</li>`).join('')}</ol>
  <details class="mill-notes"><summary>How the cutaway and drive work</summary>
  <p>The front housing is an open frame: three bearing bosses carry the roller journals and are tied to the posts by bars, so the chute and the feed nip stay visible. The upper half of the cylinder barrel is removed to show the piston. The crank shaft carries the 20-tooth pinion, so the top roller turns once for every three crank revolutions. Its crown gear meshes with equal crown gears on the feed and discharge rollers, so the two bottom rollers turn the same way as each other and opposite to the top roller; at each nip the facing surfaces move together at the same speed and draw the cane through. Juice is credited as the stalk length passes each nip. After one crank revolution 96% of a stalk has passed the feed nip and its tail is still on the chute, just short of the nip. "Inspection: remove front cheek" takes off the front housing and cuts the rollers, shafts, turnplate and chute on the plane of the cane lane; the orange faces are the cut surfaces.</p>
  <p>Idealized kinematics only: no steam pressure, torque, friction or real extraction rates. Juice per nip is a fixed teaching share per stalk.</p></details>`
  const $ = id => root.querySelector('#' + id)
  const svg = $('art')

  function frame() {
    const w = Math.max(300, Math.min(900, root.clientWidth || 600))
    const h = Math.round(w < 560 ? w * 0.92 : w * 0.6)
    if (w !== W || !S) { W = w; H = h; S = scene(W, H); svg.setAttribute('viewBox', `0 0 ${W} ${H}`) }
  }
  function paint() {
    frame()
    const marks = MARKS.map((m, i) => { const [x, y] = k.iso(m[1](), S.P); return `<g class="mill-mark"><circle cx="${x.toFixed(1)}" cy="${y.toFixed(1)}" r="8.5"/><text x="${x.toFixed(1)}" y="${(y + 3.6).toFixed(1)}" text-anchor="middle">${i + 1}</text></g>` }).join('')
    S.cut = cut
    $('cut').setAttribute('aria-pressed', String(cut))
    svg.innerHTML = draw(st, S) + marks
    const p = M.pose(st), deg = ((st.crank * 180 / Math.PI) % 360 + 360) % 360
    $('status').textContent = st.msg
    $('rpmv').textContent = `${st.rpm} rpm`
    $('play').textContent = playing ? 'Pause' : 'Play'
    $('play').setAttribute('aria-pressed', String(playing))
    const rows = [
      ['Crank angle', `${deg.toFixed(0)}°`],
      ['Piston travel', `${(p.sc.displacement ?? 0).toFixed(2)} of ${(2 * M.crank.radius).toFixed(1)} units`],
      ['Roller speed', `${(st.rpm * M.ratio).toFixed(1)} rpm`],
      ['Cane surface speed', `${M.surfaceSpeed(st.rpm).toFixed(2)} units/s`],
      ['Stalks fed / discharged', `${st.fed} / ${st.done}`],
      ['Juice', `${st.juice.toFixed(2)} L`],
    ]
    $('readout').innerHTML = rows.map(([a, b]) => `<div><dt>${a}</dt><dd>${b}</dd></div>`).join('')
  }
  function tick(t) {
    raf = 0
    if (!alive || !playing || !visible) return
    const dt = last == null ? 0 : Math.min(0.1, (t - last) / 1000)
    last = t
    st = M.advance(st, dt)
    paint()
    raf = requestAnimationFrame(tick)
  }
